use std::sync::Arc;
use std::thread;

fn w1(s: &Arc<Semaphore>) {
    let _permit = s.acquire();
    // perform work while holding the permit
    drop(_permit);
}

fn w2(s: &Arc<Semaphore>) {
    let _permit = s.acquire();
    // perform work while holding the permit
    drop(_permit);
}

fn w3(s: &Arc<Semaphore>) {
    let _permit = s.acquire();
    // perform work while holding the permit
    drop(_permit);
}

fn main() {
    let s = Semaphore::new(2);

    let s1 = Arc::clone(&s);
