use concir_sync::Semaphore;
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

fn w1(m: &Arc<Mutex<bool>>, cv: &Arc<Condvar>, g12: &Arc<Semaphore>) {
    // s1: mutex_lock m
    let mut go_guard = m.lock().unwrap();
    // s2: semaphore_release g12
    g12.acquire().release();
    // s3/s4/s5: branch on go, condvar_wait while go == false
    while !*go_guard {
        go_guard = cv.wait(go_guard).unwrap();
    }
    // s6: mutex_unlock m
    drop(go_guard);
    // s7: return
}

fn w2(m: &Arc<Mutex<bool>>, cv: &Arc<Condvar>, g12: &Arc<Semaphore>) {
    // s1: mutex_lock m
    let mut go_guard = m.lock().unwrap();
    // s2: semaphore_release g12
    g12.acquire().release();
    // s3/s4/s5: branch on go, condvar_wait while go == false
    while !*go_guard {
        go_guard = cv.wait(go_guard).unwrap();
    }
    // s6: mutex_unlock m
    drop(go_guard);
    // s7: return
}

fn notifier(
    m: &Arc<Mutex<bool>>,
    cv: &Arc<Condvar>,
    g12: &Arc<Semaphore>,
    g_n: &Arc<Semaphore>,
) {
    // s1: semaphore_acquire g12 (count 2)
    let p1 = g12.acquire();
    let p2 = g12.acquire();
    // s2: mutex_lock m
    let mut go_guard = m.lock().unwrap();
    // s3: write_shared go = true
    *go_guard = true;
    // s4: condvar_notify_all cv
    cv.notify_all();
    // s5: mutex_unlock m
    drop(go_guard);
    // s6: semaphore_release gN
    let pn = g_n.acquire();
    drop(pn);
    drop(p1);
    drop(p2);
    // s7: return
}

fn main() {
    // resources: m (Mutex guarding var go), cv (Condvar), g12, gN (semaphores)
    let m: Arc<Mutex<bool>> = Arc::new(Mutex::new(false)); // var go, init false, protected by m
    let cv: Arc<Condvar> = Arc::new(Condvar::new());
    let g12: Arc<Semaphore> = Semaphore::new(0);
    let g_n: Arc<Semaphore> = Semaphore::new(0);

